const { Given, When, Then } = require('@cucumber/cucumber');
const assert = require('assert');

// Background
Given('the app is loaded', function () {
  // App is already loaded by world.js Before hook
  assert.ok(this.document, 'App should be loaded');
});

// Adding todos
When('I type {string} in the new todo input', function (text) {
  const input = this.document.querySelector('.new-todo');
  input.value = text;
});

When('I press Enter', function () {
  // Check if we're in edit mode
  const editInput = this.document.querySelector('.todo-list li.editing .edit');
  if (editInput) {
    editInput.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Enter', bubbles: true }));
  } else {
    const input = this.document.querySelector('.new-todo');
    input.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Enter', bubbles: true }));
  }
});

Then('I should see {string} in the todo list', function (text) {
  const labels = this.document.querySelectorAll('.todo-list label');
  const found = Array.from(labels).some(l => l.textContent === text);
  assert.ok(found, `Expected to see "${text}" in todo list`);
});

Then('the new todo input should be empty', function () {
  const input = this.document.querySelector('.new-todo');
  assert.strictEqual(input.value, '', 'New todo input should be empty');
});

Then('I should see no todos', function () {
  const items = this.document.querySelectorAll('.todo-list li');
  assert.strictEqual(items.length, 0, 'Expected no todos');
});

// Toggle todos
Given('I have a todo {string}', function (text) {
  const input = this.document.querySelector('.new-todo');
  input.value = text;
  input.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Enter', bubbles: true }));
});

Given('I have a completed todo {string}', function (text) {
  const input = this.document.querySelector('.new-todo');
  input.value = text;
  input.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Enter', bubbles: true }));
  // Find and toggle the todo
  const labels = this.document.querySelectorAll('.todo-list label');
  const label = Array.from(labels).find(l => l.textContent === text);
  assert.ok(label, `Expected to find "${text}"`);
  const li = label.closest('li');
  const toggle = li.querySelector('.toggle');
  toggle.click();
});

When('I toggle the todo {string}', function (text) {
  const labels = this.document.querySelectorAll('.todo-list label');
  const label = Array.from(labels).find(l => l.textContent === text);
  assert.ok(label, `Expected to find "${text}"`);
  const li = label.closest('li');
  const toggle = li.querySelector('.toggle');
  toggle.click();
});

Then('the todo {string} should be completed', function (text) {
  const labels = this.document.querySelectorAll('.todo-list label');
  const label = Array.from(labels).find(l => l.textContent === text);
  assert.ok(label, `Expected to find "${text}"`);
  const li = label.closest('li');
  assert.ok(li.classList.contains('completed'), `Expected "${text}" to be completed`);
});

Then('the todo {string} should be active', function (text) {
  const labels = this.document.querySelectorAll('.todo-list label');
  const label = Array.from(labels).find(l => l.textContent === text);
  assert.ok(label, `Expected to find "${text}"`);
  const li = label.closest('li');
  assert.ok(!li.classList.contains('completed'), `Expected "${text}" to be active`);
});

// Delete todos
When('I delete the todo {string}', function (text) {
  const labels = this.document.querySelectorAll('.todo-list label');
  const label = Array.from(labels).find(l => l.textContent === text);
  assert.ok(label, `Expected to find "${text}"`);
  const li = label.closest('li');
  const destroy = li.querySelector('.destroy');
  destroy.click();
});

// Edit todos
When('I double-click the todo {string}', function (text) {
  const labels = this.document.querySelectorAll('.todo-list label');
  const label = Array.from(labels).find(l => l.textContent === text);
  assert.ok(label, `Expected to find "${text}"`);
  label.dispatchEvent(new this.window.Event('dblclick', { bubbles: true }));
});

When('I type {string} in the edit input', function (text) {
  const editInput = this.document.querySelector('.todo-list li.editing .edit');
  assert.ok(editInput, 'Expected edit input to be visible');
  editInput.value = text;
  editInput.dispatchEvent(new this.window.Event('input', { bubbles: true }));
});

When('I press Escape', function () {
  const editInput = this.document.querySelector('.todo-list li.editing .edit');
  assert.ok(editInput, 'Expected edit input to be visible');
  editInput.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Escape', bubbles: true }));
});

Then('I should not see {string} in the todo list', function (text) {
  const labels = this.document.querySelectorAll('.todo-list label');
  const found = Array.from(labels).some(l => l.textContent === text);
  assert.ok(!found, `Expected not to see "${text}" in todo list`);
});

// Toggle all
Given('I have todos {string} and {string}', function (text1, text2) {
  const input = this.document.querySelector('.new-todo');
  input.value = text1;
  input.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Enter', bubbles: true }));
  input.value = text2;
  input.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Enter', bubbles: true }));
});

Given('I have completed todos {string} and {string}', function (text1, text2) {
  const input = this.document.querySelector('.new-todo');
  input.value = text1;
  input.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Enter', bubbles: true }));
  input.value = text2;
  input.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Enter', bubbles: true }));
  // Toggle all to complete
  const toggleAll = this.document.getElementById('toggle-all');
  toggleAll.click();
});

When('I toggle all todos', function () {
  const toggleAll = this.document.getElementById('toggle-all');
  toggleAll.click();
});

Then('all todos should be completed', function () {
  const items = this.document.querySelectorAll('.todo-list li');
  items.forEach(li => {
    assert.ok(li.classList.contains('completed'), 'Expected todo to be completed');
  });
});

Then('all todos should be active', function () {
  const items = this.document.querySelectorAll('.todo-list li');
  items.forEach(li => {
    assert.ok(!li.classList.contains('completed'), 'Expected todo to be active');
  });
});

// Clear completed
When('I click clear completed', function () {
  const clearButton = this.document.querySelector('.clear-completed');
  clearButton.click();
});

// Counter
Then('the counter should show {string}', function (text) {
  const todoCount = this.document.querySelector('.todo-count');
  assert.ok(todoCount.textContent.includes(text), `Expected counter to show "${text}"`);
});

// Filtering
When('I click the {string} filter', function (filterName) {
  const links = this.document.querySelectorAll('.filters a');
  const link = Array.from(links).find(a => a.textContent === filterName);
  assert.ok(link, `Expected to find "${filterName}" filter`);
  link.click();
});

// Visibility
Then('the main section should be hidden', function () {
  const main = this.document.querySelector('.main');
  assert.strictEqual(main.style.display, 'none', 'Expected main section to be hidden');
});

Then('the main section should be visible', function () {
  const main = this.document.querySelector('.main');
  assert.notStrictEqual(main.style.display, 'none', 'Expected main section to be visible');
});

Then('the footer should be hidden', function () {
  const footer = this.document.querySelector('.footer');
  assert.strictEqual(footer.style.display, 'none', 'Expected footer to be hidden');
});

Then('the footer should be visible', function () {
  const footer = this.document.querySelector('.footer');
  assert.notStrictEqual(footer.style.display, 'none', 'Expected footer to be visible');
});

// Edit interaction safety
When('I clear the edit input', function () {
  const editInput = this.document.querySelector('.todo-list li.editing .edit');
  assert.ok(editInput, 'Expected edit input to be visible');
  editInput.value = '';
});

When('I press Enter in the edit input and blur fires', function () {
  const editInput = this.document.querySelector('.todo-list li.editing .edit');
  assert.ok(editInput, 'Expected edit input to be visible');
  // Fire blur first (as the real browser does), then Enter
  editInput.dispatchEvent(new this.window.Event('blur', { bubbles: true }));
  editInput.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Enter', bubbles: true }));
});

Then('no error is thrown', function () {
  // If we reached here without an exception, no error was thrown
  assert.ok(true, 'No error was thrown');
});

// Routing
Then('the URL hash should be {string}', function (expected) {
  assert.strictEqual(this.window.location.hash, expected, `Expected URL hash to be "${expected}"`);
});

When('I navigate back', function () {
  this.window.history.back();
  this.window.dispatchEvent(new this.window.Event('hashchange'));
});

When('I navigate to {string}', function (hash) {
  this.navigate(hash);
});

// Anchor default check
Given('the app source at {string}', function (appPath) {
  // Load the app source for inspection
  const fs = require('node:fs');
  const path = require('node:path');
  const fullPath = path.join(path.resolve(__dirname, '..', '..'), appPath);
  this.appSource = fs.readFileSync(fullPath, 'utf8');
});

Then('the filter click handler does not call {string}', function (method) {
  assert.ok(this.appSource, 'App source should be loaded');
  // Find the handleFilterClick function and verify it does not call preventDefault
  const handlerMatch = this.appSource.match(/function\s+handleFilterClick[\s\S]*?(?=function\s+|$)/);
  assert.ok(handlerMatch, 'handleFilterClick function not found');
  const handlerBody = handlerMatch[0];
  assert.ok(
    !handlerBody.includes(method),
    `Expected handleFilterClick to NOT call ${method}`
  );
});

const fs = require('node:fs');
const path = require('node:path');
const { setWorldConstructor, Before, After } = require('@cucumber/cucumber');
const { Window } = require('happy-dom');

const ROOT = path.resolve(__dirname, '..', '..');

class AppWorld {
  // Load the REAL page and the REAL app. A missing artifact is a loud failure here, not a
  // silently-green suite: the executable tier must exercise the production artifact.
  loadApp() {
    const indexPath = path.join(ROOT, 'index.html');
    const appPath = path.join(ROOT, 'js', 'app.js');
    if (!fs.existsSync(indexPath))
      throw new Error(`verification support: ${indexPath} does not exist — the app has no page to load`);
    if (!fs.existsSync(appPath))
      throw new Error(`verification support: ${appPath} does not exist — the app has no code to run`);
    const appSource = fs.readFileSync(appPath, 'utf8');
    if (appSource.trim().length === 0)
      throw new Error(`verification support: ${appPath} is empty — there is no application to verify`);

    // disableJavaScriptFileLoading: the harness executes app.js itself as inline source, and a
    // real <script src> under happy-dom attempts a network fetch (ECONNREFUSED, pilot 0.13.64).
    this.window = new Window({
      url: 'http://localhost/',
      settings: { disableJavaScriptFileLoading: true },
    });
    this.document = this.window.document;

    // The app must EXECUTE, not merely be present. Two things were measured 2026-07-28 and both
    // bit an earlier version of this harness:
    //   1. happy-dom does NOT run scripts the parser sees — neither an appended <script> with
    //      textContent nor one inlined into document.write(). window.eval() DOES run them. An
    //      earlier harness looked green while app.js never ran, because its only assertion
    //      checked that the PAGE had loaded. A weak test hid a broken loader.
    //   2. DOMContentLoaded never fires from write()/close(), so an app that defers its init to
    //      DOMContentLoaded or window.load — the common TodoMVC shape — would never initialise
    //      and the harness would fail CORRECT code. The lifecycle events are dispatched here.
    // disableJavaScriptFileLoading stops the page's own src tag attempting a network fetch
    // (ECONNREFUSED under happy-dom, pilot 0.13.64).
    this.document.write(fs.readFileSync(indexPath, 'utf8'));
    this.document.close();
    this.window.eval(appSource);
    this.document.dispatchEvent(new this.window.Event('DOMContentLoaded', { bubbles: true }));
    this.window.dispatchEvent(new this.window.Event('load'));

    // ROUTING. happy-dom updates location.hash but NEVER fires hashchange — measured
    // 2026-07-28, both by assignment and by clicking an in-page anchor. A TodoMVC router
    // listens for hashchange, so without this the filter/back-button behaviour is
    // UNREACHABLE in this tier: one wave spent seven correction voyages implementing filter
    // links that nothing could ever drive, stuck at 22/29 the whole way. Route the two ways a
    // real browser changes the hash, so routing is exercisable rather than merely present.
    const w = this.window;
    this.document.addEventListener('click', (e) => {
      const a = e.target && e.target.closest ? e.target.closest('a[href^="#"]') : null;
      if (!a) return;
      const next = a.getAttribute('href');
      if (w.location.hash !== next) { w.location.hash = next; w.dispatchEvent(new w.Event('hashchange')); }
    }, true);
    return this.document;
  }

  // Drive the router the way a user's address bar does.
  navigate(hash) {
    if (!this.window) throw new Error('verification support: navigate() before the app was loaded');
    if (this.window.location.hash === hash) return;
    this.window.location.hash = hash;
    this.window.dispatchEvent(new this.window.Event('hashchange'));
  }

  get localStorage() { return this.window.localStorage; }

  // A happy-dom Window holds timers, observers and native buffers; an undisposed one per
  // scenario grows without bound. Measured 2026-07-28: a wave whose own world.js never
  // disposed reached 13.6G RSS across ~45 scenarios and was OOM-killed by the kernel, which
  // ended the suite with a bare "Killed" and no summary line. NODE_OPTIONS
  // --max-old-space-size does NOT prevent this: the growth is outside V8's old space, so the
  // cap bounds the JS heap while the process still takes the box down. Disposal is the fix.
  async disposeApp() {
    const w = this.window;
    if (!w) return;
    this.window = undefined;
    this.document = undefined;
    if (w.happyDOM && typeof w.happyDOM.close === 'function') { await w.happyDOM.close(); return; }
    if (w.happyDOM && typeof w.happyDOM.abort === 'function') { await w.happyDOM.abort(); return; }
    if (typeof w.close === 'function') w.close();
  }
}

setWorldConstructor(AppWorld);

// Every scenario gets the real app. No scenario can pass without one.
Before(function () { this.loadApp(); });
// ...and every scenario gives it back.
After(async function () { await this.disposeApp(); });

